Set-StrictMode -Version Latest\n$ErrorActionPreference = "Stop"\n\nparam(\n [switch]$Apply\n)\n\nif (-not (Test-Path ".obsidian")) {\n throw "Run this from the DevNotes vault root."\n}\n\n$RunMode = if ($Apply) { "APPLY" } else { "PREVIEW" }\n$Today = Get-Date -Format "yyyy-MM-dd"\n$VaultRoot = (Get-Location).Path\n$ReportDir = "*OPS"\n$ReportPath = Join-Path $ReportDir "property-normalization-pass1.csv"\n\nif (-not (Test-Path -LiteralPath $ReportDir)) {\n New-Item -ItemType Directory -Force -Path $ReportDir | Out-Null\n}\n\nfunction Get-RelPath {\n param([string]$FullPath)\n return $FullPath.Substring($VaultRoot.Length).TrimStart("\","/")\n}\n\nfunction Convert-ToSlug {\n param([string]$Value)\n\n if ([string]::IsNullOrWhiteSpace($Value)) {\n return "unknown"\n }\n\n $slug = $Value.ToLowerInvariant()\n $slug = $slug -replace "&", "and"\n $slug = $slug -replace "[^a-z0-9]+", "-"\n $slug = $slug.Trim("-")\n\n if ([string]::IsNullOrWhiteSpace($slug)) {\n return "unknown"\n }\n\n return $slug\n}\n\nfunction Convert-ToTitle {\n param([string]$Value)\n\n if ([string]::IsNullOrWhiteSpace($Value)) {\n return "Untitled"\n }\n\n $clean = $Value\n $clean = $clean -replace "\.md$", ""\n $clean = $clean -replace "\.", " "\n $clean = $clean -replace "[-*]+", " "\n $clean = $clean.Trim()\n\n if ([string]::IsNullOrWhiteSpace($clean)) {\n return "Untitled"\n }\n\n return (Get-Culture).TextInfo.ToTitleCase($clean.ToLowerInvariant())\n}\n\nfunction Format-YamlScalar {\n param([AllowNull()][string]$Value)\n\n if ($null -eq $Value -or $Value -eq "") {\n return ""\n }\n\n $escaped = $Value.Replace('"','\"')\n return '"' + $escaped + '"'\n}\n\nfunction Test-YamlHasKey {\n param(\n [string]$Yaml,\n [string]$Key\n )\n\n return [regex]::IsMatch($Yaml, "(?m)^\s*$([regex]::Escape($Key))\s*:")\n}\n\nfunction Get-FirstHeading {\n param([string]$Text)\n\n $m = [regex]::Match($Text, "(?m)^#\s+(?<title>.+?)\s*$")\n if ($m.Success) {\n return $m.Groups["title"].Value.Trim()\n }\n\n return $null\n}\n\nfunction Get-ProjectFromPath {\n param([string]$RelPath)\n\n $m = [regex]::Match($RelPath, "^10 PROJECTS[\\/](?<project>[^\\/]+)[\\/]")\n if ($m.Success) {\n return $m.Groups["project"].Value\n }\n\n return ""\n}\n\nfunction Get-ProjectSection {\n param([string]$RelPath)\n\n $m = [regex]::Match($RelPath, "^10 PROJECTS[\\/][^\\/]+[\\/](?<section>[^\\/]+)")\n if ($m.Success) {\n return $m.Groups["section"].Value\n }\n\n return ""\n}\n\nfunction Get-TopDomain {\n param([string]$RelPath)\n\n if ($RelPath -like "00 ZETTELKASTEN/*") { return "zettelkasten" }\n if ($RelPath -like "10 PROJECTS/*") { return "projects" }\n if ($RelPath -like "20 DOCUMENTATION/*") { return "documentation" }\n if ($RelPath -like "30 DEEP RESEARCH/*") { return "deep-research" }\n if ($RelPath -like "40 TECH STACK/*") { return "tech-stack" }\n if ($RelPath -like "50 REGRETS, CIGARETTES, & NEURAL NETS/*") { return "writing" }\n if ($RelPath -like "90 OBSIDIAN/*") { return "obsidian" }\n return "vault"\n}\n\nfunction Get-DomainFromPath {\n param(\n [string]$RelPath,\n [string]$Project\n )\n\n if ($Project) {\n $section = Get-ProjectSection $RelPath\n\n if ($section -eq "00 PROJECT MAP") { return "project" }\n if ($section -eq "10 PRODUCT") { return "product" }\n if ($section -eq "30 ARCHITECTURE") { return "architecture" }\n if ($section -eq "40 FEATURES") { return "features" }\n if ($section -eq "50 AGENT OPS") { return "agent-ops" }\n if ($section -eq "60 EXECUTION") { return "execution" }\n if ($section -eq "70 RESEARCH") { return "research" }\n if ($section -eq "80 LEGAL") { return "legal" }\n if ($section -eq "90 ARCHIVE") { return "archive" }\n\n $m = [regex]::Match($RelPath, "^10 PROJECTS[\\/][^\\]+[\\/]20 CONTRACTS[\\/](?<domain>[^\\/]+)")\n if ($m.Success) {\n return $m.Groups["domain"].Value\n }\n\n if ($section -eq "20 CONTRACTS") { return "contracts" }\n\n return "project"\n }\n\n return Get-TopDomain $RelPath\n}\n\nfunction Get-TypeFromPath {\n param(\n [string]$RelPath,\n [string]$FileBase,\n [string]$Domain\n )\n\n if ($RelPath -like "90 OBSIDIAN/OB-Templates/*") { return "template" }\n if ($RelPath -like "90 OBSIDIAN/Dashboards/*") { return "dashboard" }\n if ($RelPath -like "90 OBSIDIAN/Workflows/*") { return "workflow" }\n if ($RelPath -like "90 OBSIDIAN/Contracts/*") { return "standard" }\n if ($FileBase -match "\.contract$" -or $RelPath -like "*/20 CONTRACTS/*") { return "contract" }\n if ($FileBase -match "\.map$" -or $RelPath -like "*/00 PROJECT MAP/*") { return "map" }\n if ($FileBase -match "\.workflow$") { return "workflow" }\n if ($FileBase -match "\.dashboard$") { return "dashboard" }\n if ($FileBase -match "\.legacy$" -or $RelPath -like "*/90 ARCHIVE/*") { return "legacy" }\n\n if ($Domain -eq "research" -or $RelPath -like "30 DEEP RESEARCH/*") { return "research" }\n if ($Domain -eq "documentation" -or $Domain -eq "tech-stack" -or $RelPath -like "20 DOCUMENTATION/*" -or $RelPath -like "40 TECH STACK/*") { return "reference" }\n if ($Domain -eq "writing" -or $RelPath -like "50 REGRETS, CIGARETTES, & NEURAL NETS/*") { return "writing" }\n if ($Domain -eq "execution") { return "execution" }\n if ($Domain -eq "legal") { return "legal" }\n if ($Domain -eq "architecture") { return "architecture" }\n if ($Domain -eq "product") { return "product" }\n if ($Domain -eq "features") { return "feature" }\n if ($Domain -eq "zettelkasten") { return "capture" }\n\n return "note"\n}\n\nfunction Get-KindFromTypeAndName {\n param(\n [string]$Type,\n [string]$FileBase\n )\n\n if ($FileBase -match "\.contract$") { return "contract" }\n if ($FileBase -match "\.map$") { return "map" }\n if ($FileBase -match "\.workflow$") { return "workflow" }\n if ($FileBase -match "\.dashboard$") { return "dashboard" }\n if ($FileBase -match "\.legacy$") { return "legacy" }\n if ($FileBase -match "\.spec$") { return "spec" }\n if ($FileBase -match "\.checklist$") { return "checklist" }\n if ($FileBase -match "\.work-package$") { return "work-package" }\n if ($FileBase -match "\.handoff$") { return "handoff" }\n\n return $Type\n}\n\nfunction Get-Namespace {\n param(\n [string]$RelPath,\n [string]$FileBase,\n [string]$Project,\n [string]$Domain\n )\n\n if ($FileBase -match "\.") {\n return $FileBase.ToLowerInvariant()\n }\n\n $fileSlug = Convert-ToSlug $FileBase\n\n if ($Project) {\n $projectSlug = Convert-ToSlug $Project\n return "$projectSlug.$Domain.$fileSlug"\n }\n\n $topDomain = Get-TopDomain $RelPath\n\n if ($topDomain -eq "obsidian") {\n return "obsidian.$fileSlug"\n }\n\n return "devnotes.$topDomain.$fileSlug"\n}\n\nfunction Get-Artifact {\n param(\n [string]$Namespace,\n [string]$Project,\n [string]$Domain,\n [string]$Kind,\n [string]$FileBase\n )\n\n $parts = @($Namespace.Split(".") | Where-Object { $* })\n\n if ($parts.Count -ge 3) {\n $start = 2\n $end = $parts.Count - 1\n\n if ($parts[$parts.Count - 1] -eq $Kind -and $parts.Count -ge 4) {\n $end = $parts.Count - 2\n }\n\n if ($end -ge $start) {\n return ($parts[$start..$end] -join ".")\n }\n }\n\n return Convert-ToSlug $FileBase\n}\n\nfunction Get-Status {\n param(\n [string]$RelPath,\n [string]$FileBase,\n [string]$Type\n )\n\n if ($FileBase -match "\.legacy$" -or $RelPath -like "*/90 ARCHIVE/*") { return "legacy" }\n if ($RelPath -like "00 ZETTELKASTEN/*") { return "draft" }\n if ($Type -eq "template") { return "active" }\n if ($Type -eq "contract" -and $RelPath -like "90 OBSIDIAN/OB-Templates/*") { return "active" }\n return "active"\n}\n\nfunction Get-Authority {\n param(\n [string]$Type,\n [string]$Status,\n [string]$RelPath\n )\n\n if ($Status -eq "legacy") { return "legacy" }\n if ($Type -in @("contract","map","standard","workflow")) { return "source-of-truth" }\n if ($Type -in @("reference","research","writing","template","dashboard")) { return "reference" }\n if ($Type -in @("capture","execution")) { return "working-note" }\n return "reference"\n}\n\nfunction Get-Parent {\n param(\n [string]$Project,\n [string]$Type,\n [string]$Namespace,\n [string]$RelPath\n )\n\n if ($Namespace -eq "devnotes.home") { return "" }\n if ($Namespace -eq "devnotes.projects.map") { return "[[devnotes.home]]" }\n\n if ($Project) {\n $projectSlug = Convert-ToSlug $Project\n if ($Namespace -eq "$projectSlug.project.map") {\n return "[[devnotes.projects.map]]"\n }\n\n return "[[$projectSlug.project.map]]"\n }\n\n if ($RelPath -like "00 ZETTELKASTEN/*") { return "[[devnotes.zettelkasten.map]]" }\n if ($RelPath -like "20 DOCUMENTATION/*") { return "[[devnotes.documentation.map]]" }\n if ($RelPath -like "30 DEEP RESEARCH/*") { return "[[devnotes.deep-research.map]]" }\n if ($RelPath -like "40 TECH STACK/*") { return "[[devnotes.tech-stack.map]]" }\n if ($RelPath -like "50 REGRETS, CIGARETTES, & NEURAL NETS/*") { return "[[devnotes.regrets-cigarettes-neural-nets.map]]" }\n if ($RelPath -like "90 OBSIDIAN/*") { return "[[obsidian.system.map]]" }\n\n return "[[devnotes.home]]"\n}\n\nfunction Get-Tags {\n param(\n [string]$Project,\n [string]$Domain,\n [string]$Type,\n [string]$Status,\n [string]$Kind\n )\n\n $tags = New-Object System.Collections.Generic.List[string]\n\n if ($Project) {\n $tags.Add("projects/$(Convert-ToSlug $Project)")\n }\n\n if ($Domain) {\n $tags.Add("domains/$Domain")\n }\n\n if ($Type) {\n $tags.Add("types/$Type")\n }\n\n if ($Kind -and $Kind -ne $Type) {\n $tags.Add("kinds/$Kind")\n }\n\n if ($Status) {\n $tags.Add("status/$Status")\n }\n\n return @($tags | Select-Object -Unique)\n}\n\nfunction Get-MetaForFile {\n param(\n [string]$RelPath,\n [string]$Text,\n [System.IO.FileInfo]$File\n )\n\n $fileBase = [System.IO.Path]::GetFileNameWithoutExtension($File.Name)\n $heading = Get-FirstHeading $Text\n $title = if ($heading) { $heading } else { Convert-ToTitle $fileBase }\n\n $project = Get-ProjectFromPath $RelPath\n $scope = if ($project) { "project" } elseif ($RelPath -like "90 OBSIDIAN/*") { "vault" } else { "reference" }\n $domain = Get-DomainFromPath $RelPath $project\n $type = Get-TypeFromPath $RelPath $fileBase $domain\n $kind = Get-KindFromTypeAndName $type $fileBase\n $namespace = Get-Namespace $RelPath $fileBase $project $domain\n $artifact = Get-Artifact $namespace $project $domain $kind $fileBase\n $status = Get-Status $RelPath $fileBase $type\n $authority = Get-Authority $type $status $RelPath\n $parent = Get-Parent $project $type $namespace $RelPath\n $tags = Get-Tags $project $domain $type $status $kind\n\n return [ordered]@{\n title = $title\n type = $type\n scope = $scope\n project = $project\n domain = $domain\n artifact = $artifact\n kind = $kind\n namespace = $namespace\n status = $status\n authority = $authority\n parent = $parent\n depends_on = @()\n supersedes = @()\n tags = $tags\n created = $File.CreationTime.ToString("yyyy-MM-dd")\n updated = $Today\n }\n}\n\nfunction New-YamlLines {\n param([hashtable]$Meta)\n\n $lines = New-Object System.Collections.Generic.List[string]\n\n $lines.Add("title: $(Format-YamlScalar $Meta.title)")\n $lines.Add("type: $($Meta.type)")\n $lines.Add("scope: $($Meta.scope)")\n if ($Meta.project) { $lines.Add("project: $($Meta.project)") } else { $lines.Add("project:") }\n $lines.Add("domain: $($Meta.domain)")\n $lines.Add("artifact: $($Meta.artifact)")\n $lines.Add("kind: $($Meta.kind)")\n $lines.Add("namespace: $($Meta.namespace)")\n $lines.Add("status: $($Meta.status)")\n $lines.Add("authority: $($Meta.authority)")\n if ($Meta.parent) { $lines.Add("parent: $(Format-YamlScalar $Meta.parent)") } else { $lines.Add("parent:") }\n $lines.Add("depends_on: []")\n $lines.Add("supersedes: []")\n $lines.Add("tags:")\n foreach ($tag in $Meta.tags) {\n $lines.Add(" - $tag")\n }\n $lines.Add("created: $($Meta.created)")\n $lines.Add("updated: $($Meta.updated)")\n\n return @($lines)\n}\n\nfunction Add-OrCompleteFrontmatter {\n param(\n [string]$Text,\n [hashtable]$Meta\n )\n\n $allLines = New-YamlLines $Meta\n\n $frontmatterMatch = [regex]::Match($Text, "(?s)^---\r?\n(?<yaml>.*?)\r?\n---(?<rest>.*)$")\n\n if (-not $frontmatterMatch.Success) {\n $yaml = ($allLines -join "`n\")\n return \"---`n$yaml`n---`n`n$Text\"\n }\n\n $yamlExisting = $frontmatterMatch.Groups[\"yaml\"].Value\n $rest = $frontmatterMatch.Groups[\"rest\"].Value\n $missing = New-Object System.Collections.Generic.List[string]\n\n $keyBuffer = $null\n\n foreach ($line in $allLines) {\n if ($line -match \"^(?<key>[A-Za-z0-9_-]+):\") {\n $key = $Matches.key\n\n if (-not (Test-YamlHasKey $yamlExisting $key)) {\n $missing.Add($line)\n $keyBuffer = $key\n } else {\n $keyBuffer = $null\n }\n\n continue\n }\n\n if ($keyBuffer) {\n $missing.Add($line)\n }\n }\n\n if ($missing.Count -eq 0) {\n return $Text\n }\n\n $yamlNew = $yamlExisting.TrimEnd() + \"`n" + ($missing -join "`n\")\n return \"---`n$yamlNew`n---$rest"\n}\n\n$files = Get-ChildItem -LiteralPath "." -Recurse -File -Filter "*.md" |\n Where-Object {\n $rel = Get-RelPath $_.FullName\n\n $rel -notlike ".obsidian/*" -and\n $rel -notlike ".git/*" -and\n $rel -notlike ".agent-logs/*" -and\n $rel -notlike "_OPS/*" -and\n $rel -notlike "90 OBSIDIAN/OB-Templates/*"\n }\n\n$report = New-Object System.Collections.Generic.List[object]\n$changed = 0\n$unchanged = 0\n\nforeach ($file in $files) {\n $rel = Get-RelPath $file.FullName\n $text = Get-Content -Raw -LiteralPath $file.FullName\n $meta = Get-MetaForFile $rel $text $file\n $newText = Add-OrCompleteFrontmatter $text $meta\n $willChange = ($newText -ne $text)\n\n if ($willChange) {\n $changed++\n\n if ($Apply) {\n $newText | Set-Content -LiteralPath $file.FullName -Encoding UTF8\n Write-Host "NORMALIZE $rel" -ForegroundColor Cyan\n } else {\n Write-Host "WOULD NORMALIZE $rel" -ForegroundColor Yellow\n }\n } else {\n $unchanged++\n }\n\n $report.Add([pscustomobject]@{\n path = $rel\n title = $meta.title\n type = $meta.type\n scope = $meta.scope\n project = $meta.project\n domain = $meta.domain\n artifact = $meta.artifact\n kind = $meta.kind\n namespace = $meta.namespace\n status = $meta.status\n authority = $meta.authority\n parent = $meta.parent\n changed = $willChange\n })\n}\n\n$report | Export-Csv -NoTypeInformation -Encoding UTF8 -Path $ReportPath\n\nWrite-Host ""\nWrite-Host "PROPERTY NORMALIZATION PASS 1: $RunMode" -ForegroundColor Green\nWrite-Host "Files scanned: $($files.Count)"\nWrite-Host "Changed: $changed"\nWrite-Host "Unchanged: $unchanged"\nWrite-Host "Report: $ReportPath"\nWrite-Host ""\ngit status --short\n}